with lines as (select id, customer_id, created_at, coupon_codes, pos, rec.qty, rec.price from carts lateral view posexplode(items) x as pos, rec), flattened as (select id, customer_id, pos, qty, explode(coupon_codes) as element from lines), enriched as (select id, customer_id, count(pos) over (partition by element, customer_id) as element_count_pos from flattened where pos is not null), enriched_carts as (select src.*, p.credit_limit, p.country from enriched src join customers p on src.customer_id = p.id), base as (select *, ceil(credit_limit) as credit_limit_whole from enriched_carts where country = 'JP') select id, customer_id, credit_limit, credit_limit_whole from base order by credit_limit desc nulls last;
